    /*  ========================================================================= */
    /*  模式 4: 全向无限制的 位置模式 (标准多旋翼) */
    /*  ========================================================================= */
    /* 'TrajectoryGeneratorXY:331' R_body_to_ned =[cos(yaw_d), -sin(yaw_d); sin(yaw_d), cos(yaw_d)]; */
    /*  --- 1. Determine Target Velocity (NED) --- */
    /* 'TrajectoryGeneratorXY:334' is_user_input = (norm(stick_xy) >= single(1e-4)); */
    is_user_input = (LW_ctrl_V1_14_261102_lw_norm_mx(stick_xy) >= 0.0001F);

