  /*  ------------------------------------------------------------------------- */
  /* 'AutoLandingBlockedDetector:464' near_ground_by_dist = dist_bottom_valid && (single(dist_bottom) < h_near_ground); */
  /*  Require established recent descent to acquire time-based eligibility. */
  /* 'AutoLandingBlockedDetector:467' near_ground_by_time_raw = (~dist_bottom_valid) && ... */
  /* 'AutoLandingBlockedDetector:468'                           (time_in_land > t_min_land) && ... */
  /* 'AutoLandingBlockedDetector:469'                           command_stable && ... */
