  /* 'AutoLandingBlockedDetector:491' candidate_started = (candidate_timer > single(0)) || stage_candidate || ... */
  /* 'AutoLandingBlockedDetector:492'                     stage_blocked || motion_blocked; */
  /* 'AutoLandingBlockedDetector:493' near_ground_by_time_hold = (~dist_bottom_valid) && ... */
  /* 'AutoLandingBlockedDetector:494'                            (near_ground_hold_timer > single(0)) && ... */
  /* 'AutoLandingBlockedDetector:495'                            candidate_started && ... */
  /* 'AutoLandingBlockedDetector:496'                            descent_commanded && ... */
  /* 'AutoLandingBlockedDetector:497'                            motion_evidence_armed && ... */
  /* 'AutoLandingBlockedDetector:498'                            low_xy_speed && ~falling_fast && ~takeoff_intent; */
  /* 'AutoLandingBlockedDetector:500' near_ground_by_time = near_ground_by_time_raw || near_ground_by_time_hold; */
  /* 'AutoLandingBlockedDetector:501' near_ground = near_ground_by_dist || near_ground_by_time; */
  real_descent_intent = ((dist_bottom_valid && (dist_bottom < b_LNDMC_ABL_ALT)) ||
    (near_ground_by_time_raw || (near_ground_by_time_raw_tmp &&
    (LW_ctrl_V1_14_261102_lw_s100_DW.near_ground_hold_timer > 0.0F) &&
    ((LW_ctrl_V1_14_261102_lw_s100_DW.candidate_timer > 0.0F) ||
     LW_ctrl_V1_14_261102_lw_s100_DW.stage_candidate ||
     LW_ctrl_V1_14_261102_lw_s100_DW.stage_blocked || motion_blocked) &&
    actual_descent_now && stage_support && landing_enable_rising && tmp_3 &&
    tmp_0)));

  /*  ------------------------------------------------------------------------- */
  /*  Support evidence */
  /*  ------------------------------------------------------------------------- */
  /*  Freeze the support baseline once a valid touchdown candidate starts showing */
