  /*  still requires both conditions, so this only prevents early contact support */
  /*  from being absorbed into the baseline. */
  /* 'AutoLandingBlockedDetector:510' pre_blocked = auto_landing_context && ... */
  /* 'AutoLandingBlockedDetector:511'               near_ground && ... */
  /* 'AutoLandingBlockedDetector:512'               descent_commanded && ... */
  /* 'AutoLandingBlockedDetector:513'               motion_evidence_armed && ... */
  /* 'AutoLandingBlockedDetector:514'               low_xy_speed && ... */
  /* 'AutoLandingBlockedDetector:515'               ~falling_fast && ... */
  /* 'AutoLandingBlockedDetector:516'               (vel_blocked || progress_blocked); */
  /* 'AutoLandingBlockedDetector:518' if ~(pre_blocked || stage_blocked) */
