  /* 'RflyDiscretePID:44' if obj.AntiWindupMethod > 2 */
  /* 'RflyDiscretePID:48' if ~isempty(config.BackCalculationGain) */
  /* 'RflyDiscretePID:49' obj.BackCalculationGain = single(config.BackCalculationGain); */
  obj->BackCalculationGain = 0.0F;

  /* 'RflyDiscretePID:51' if ~isempty(config.IntegratorInitialCondition) */
  /* 'RflyDiscretePID:52' obj.IntegratorInitialCondition = single(config.IntegratorInitialCondition); */
  obj->IntegratorInitialCondition = 0.0F;

