  LW_ctrl_V1_14_261102_lw_s100_B.y_perp_o[0] =
    (LW_ctrl_V1_14_261102_lw_s100_B.f_low_e *
     LW_ctrl_V1_14_261102_lw_s100_B.va_ref_o[0] + acc_ref[0]) * params_LW_MASS;
