        LW_ctrl_V1_14_261102_lw_s100_DW.ramp_vz_init = -9.80665F /
          LW_ctrl_V1_14_261102_lw_s100_B.Cy0;

        /* '<S45>:1:53' tilt_limit_rad = deg2rad(MPC_TILTMAX_LND); */
        LW_ctrl_V1_14_261102_lw_s100_DW.tilt_limit_rad = 0.209439516F;

