        /*  % 注意：inputs.sp_pos_z 是期望高度，inputs.cur_pos_z 是当前高度 */
        /*  if isfinite(sp_pos_z) && (sp_pos_z < cur_pos_z) */
        /*      want_takeoff = true; */
        /*   */
        /*  % 2. 检查速度 Setpoint (NED系: 速度 < 0 表示向上) */
        /*  elseif isfinite(sp_vel_z) && (sp_vel_z < -0.1) */
        /*      want_takeoff = true; */
        /*   */
        /*  % 3. 检查加速度 Setpoint (NED系: 加速度 < 0 表示向上) */
        /*  elseif isfinite(sp_acc_z) && (sp_acc_z < -0.1) */
        /*      want_takeoff = true; */
        /*  end */
        /* '<S45>:1:95' want_takeoff = want_takeoff_in; */
        vz_stopped = rtb_reset_log;
