      /*  Slew Rate 设置 (0.2 rad/s) */
      /* '<S45>:1:245' slew_rate_limit = single(0.2); */
      /* '<S45>:1:246' max_change = slew_rate_limit * dt; */
      LW_ctrl_V1_14_261102_lw_s100_B.sample_time = 0.2F *
        LW_ctrl_V1_14_261102_lw_s100_B.sf_hrt_timestamp_k.dt;

      /* '<S45>:1:248' delta_tilt = target_tilt_rad - tilt_limit_rad; */
      LW_ctrl_V1_14_261102_lw_s100_B.aSinInput = 0.0174532924F * (real32_T)
        LW_ctrl_V1_14_261102_lw_s100_B.axis_id -
        LW_ctrl_V1_14_261102_lw_s100_DW.tilt_limit_rad;

      /*  限制每次步进的变化量 */
      /* '<S45>:1:251' if abs(delta_tilt) > max_change */
      if ((real32_T)fabs(LW_ctrl_V1_14_261102_lw_s100_B.aSinInput) >
          LW_ctrl_V1_14_261102_lw_s100_B.sample_time) {
        /* '<S45>:1:252' delta_tilt = sign(delta_tilt) * max_change; */
        if (rtIsNaNF(LW_ctrl_V1_14_261102_lw_s100_B.aSinInput)) {
          LW_ctrl_V1_14_261102_lw_s100_B.Cy0 = (rtNaNF);
        } else if (LW_ctrl_V1_14_261102_lw_s100_B.aSinInput < 0.0F) {
          LW_ctrl_V1_14_261102_lw_s100_B.Cy0 = -1.0F;
        } else {
          LW_ctrl_V1_14_261102_lw_s100_B.Cy0 = (real32_T)
            (LW_ctrl_V1_14_261102_lw_s100_B.aSinInput > 0.0F);
        }

        LW_ctrl_V1_14_261102_lw_s100_B.aSinInput =
          LW_ctrl_V1_14_261102_lw_s100_B.Cy0 *
          LW_ctrl_V1_14_261102_lw_s100_B.sample_time;
      }

      /* '<S45>:1:255' tilt_limit_rad = tilt_limit_rad + delta_tilt; */
      LW_ctrl_V1_14_261102_lw_s100_DW.tilt_limit_rad +=
        LW_ctrl_V1_14_261102_lw_s100_B.aSinInput;

